func Operations() []Operation {
	out := make([]Operation, len(operations))
	copy(out, operations)
	return out
}

func OperationByID(id string) (Operation, bool) {
	for _, op := range operations {
		if op.ID == id {
			return op, true
		}
	}
	return Operation{}, false
}

